function useFetch(url) {
  const [data, setData] = useState(null);
  useEffect(() => {
    const c = new AbortController();
    fetch(url, { signal: c.signal }).then((r) => r.json()).then(setData);
    return () => c.abort();
  }, [url]);
  return data;
}
